import re


class MolerDevices:
    """MolerDevices class."""

    def __init__(self):
        """Molerdevice init method."""
        self._config = {'DEVICES': {}}

    def get_moler_device_config(self):
        """
        Return moler device config.

        :return: Moler device config.
        """
        return self._config

    def add_default_connection(self):
        """
        Add default moler connection to config dictionary.

        :return: Nothing.
        """
        config = {
            'DEFAULT_CONNECTION': {
                'CONNECTION_DESC': {
                    'io_type': 'terminal',
                    'variant': 'threaded'
                }
            }
        }

        self._config['DEVICES'].update(config)

    def add_create_at_startup(self, create_at_startup=True):
        """
        Add create at startup to config dictionary.

        :param create_at_startup: Boolean value, default True
        :return: Nothing.
        """
        config = {
            'CREATE_AT_STARTUP': True
        }
        if not create_at_startup:
            config['CREATE_AT_STARTUP'] = False

        self._config['DEVICES'].update(config)

    def add_local_unix_configuration(self, device_name='UnixLocal', root_login_cmd='sudo', root_password=None,
                                     root_prompt=r"root@.*?:.*#\s+"):
        """
        Add local unix configuration.

        :param device_name: The name of the device that will be created.
        :param root_login_cmd: root login method 'su' or 'sudo'.
        :param root_password: Optional parameter. If given root account configuration is added
        :param root_prompt: Optional parameter. Needed if root prompt is different than defined one
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'moler.device.unixlocal.UnixLocal',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': self._build_unix_local_root(
                        root_password,
                        root_prompt,
                        cmd=root_login_cmd)
                }
            }
        }

        self._config['DEVICES'].update(config)

    def add_remote_unix_configuration(self, device_name, host, login, password, root_password=None,
                                      root_prompt=r"root@.*?:.*#\s+",
                                      proxy_pc_host=None, proxy_pc_login=None, proxy_pc_password=None,
                                      root_login_cmd=None, device_class='moler.device.unixremote.UnixRemote',
                                      **kwargs):
        """
        Add remote unix configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param root_password: Optional parameter. If given root account configuration is added
        :param root_prompt: Optional parameter. Needed if root prompt is different than defined one
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :param root_login_cmd: root login method 'su' or 'sudo'.
        :param device_class: Moler device class, default 'moler.device.unixremote.UnixRemote'
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': device_class,
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'UNIX_REMOTE': self._build_execute_command_ssh(host=host,
                                                                       login=login,
                                                                       password=password,
                                                                       **kwargs)
                    }
                }
            }
        }
        if root_password is not None:
            root_login_cmd = 'su'
        elif root_login_cmd is None:
            root_login_cmd = 'sudo'

        config[device_name]['CONNECTION_HOPS']['UNIX_REMOTE'] = self._build_unix_remote_root(
            root_password,
            root_prompt,
            cmd=root_login_cmd)

        if proxy_pc_host is not None:
            self._add_proxy_pc_state(config[device_name], proxy_pc_host, proxy_pc_login, proxy_pc_password)

        self._config['DEVICES'].update(config)

    def add_remote_ute_linux_configuration(self, device_name, host, login, password, root_password=None,
                                           root_prompt=r"root@.*?:.*#\s+",
                                           proxy_pc_host=None, proxy_pc_login=None, proxy_pc_password=None,
                                           root_login_cmd=None, **kwargs):
        """
        Add remote UTE linux configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param root_password: Optional parameter. If given root account configuration is added
        :param root_prompt: Optional parameter. Needed if root prompt is different than defined one
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :param root_login_cmd: root login method 'su' or 'sudo'.
        :return: Nothing.
        """
        self.add_remote_unix_configuration(device_name, host, login, password, root_password, root_prompt,
                                           proxy_pc_host, proxy_pc_login, proxy_pc_password, root_login_cmd,
                                           device_class='ta_moler.device.ute_linux_remote.UteLinuxRemote', **kwargs)

    def add_syslog_configuration(self, device_name, host, login, password, grep=None,
                                 proxy_pc_host=None, proxy_pc_login=None, proxy_pc_password=None):
        """
        Add syslog configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param grep: If parameter is set, syslog will only save grep phrases.
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.unix_syslog.UnixSyslog',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'UNIX_REMOTE': self._build_execute_command_ssh(host=host, login=login, password=password)
                    }
                }
            }
        }
        if grep:
            config[device_name]['CONNECTION_HOPS']['UNIX_REMOTE'] = {
                'SYSLOG': {
                    'execute_command': 'start_syslog',
                    'command_params': {
                        'syslog_command': "nc -kluvp 51000 | sed 's/\x00//' | grep {}".format(grep)
                    }
                }
            }
        if proxy_pc_host is not None:
            self._add_proxy_pc_state(config[device_name], proxy_pc_host, proxy_pc_login, proxy_pc_password)
        self._config['DEVICES'].update(config)

    def add_syslog_configuration_v2(self, device_name, host, login, password,
                                    proxy_pc_host=None, proxy_pc_login=None, proxy_pc_password=None,
                                    syslog_path="/tmp/btslog2", syslog_mask="SYSLOG*"):
        """
        Add syslog configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :param use_syslog_file: flag to use sylog with file read instead of stream
        :param syslog_path: path for file to read     syslog from
        :param syslog_mask: mask for syslog file to read
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.unix_syslog.UnixSyslog',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'UNIX_REMOTE': self._build_execute_command_ssh(host=host, login=login, password=password)
                    },
                    'UNIX_REMOTE': {
                        'SYSLOG': {
                            'execute_command': 'ta_moler_tail_last_log',
                            'command_params': {
                                'path': syslog_path,
                                'mask': syslog_mask
                             }
                        }
                    }
                }
            }
        }

        if proxy_pc_host is not None:
            self._add_proxy_pc_state(config[device_name], proxy_pc_host, proxy_pc_login, proxy_pc_password)
        self._config['DEVICES'].update(config)

    def add_hub_console_configuration(self, device_name, host, port):
        """
        Add hub console configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to telnet connection.
        :param port: Port number. Required parameter to telnet connection.
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.hub.Hub',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'LINUX': self._build_execute_command_telnet(host=host, port=port)
                    }
                }
            }
        }

        self._config['DEVICES'].update(config)

    def add_hub_configuration(self, device_name, host, login, password, proxy_pc_host, proxy_pc_login,
                              proxy_pc_password):
        """
        Add hub configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param proxy_pc_host: Proxy_pc host address. Required parameter to ssh connection.
        :param proxy_pc_login: Proxy_pc user login. Required parameter to ssh connection.
        :param proxy_pc_password: Proxy_pc user password address. Required parameter to ssh connection.
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.hub.Hub',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'PROXY_PC': self._build_execute_command_ssh(host=proxy_pc_host, login=proxy_pc_login,
                                                                    password=proxy_pc_password)
                    },
                    'PROXY_PC': {
                        'LINUX': self._build_execute_command_ssh(host=host, login=login, password=password,
                                                                 set_default_prompt=False)
                    },
                    'LINUX': {
                        'PROXY_PC': {
                            'command_params': {
                                'expected_prompt': self._build_default_propmt(login=proxy_pc_login),
                            }
                        }
                    }
                }
            }
        }

        self._config['DEVICES'].update(config)

    def add_ru_configuration(self, device_name, host, login, password, proxy_pc_host=None, proxy_pc_login=None,  # noqa: C901
                             proxy_pc_password=None, bts_host=None, bts_login=None, bts_password=None,
                             initial_state="RU", bts_prompt=None, secondary_smod_host=None, secondary_smod_login=None,
                             secondary_smod_password=None, secondary_smod_prompt=None, port=None, serial_number=None):
        """
        Add ru configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param proxy_pc_host: Proxy_pc host address. Required parameter to ssh connection.
        :param proxy_pc_login: Proxy_pc user login. Required parameter to ssh connection.
        :param proxy_pc_password: Proxy_pc user password. Required parameter to ssh connection.
        :param bts_host:  Bts host address. Required parameter to ssh connection.
        :param bts_login: Bts user login. Required parameter to ssh connection.
        :param bts_password: Bts user password. Required parameter to ssh connection.
        :param initial_state: Initial state after establish connection.
        :param bts_prompt: Prompt regex for BTS state.
        :param secondary_smod_host: IP address for Secondary SMOD.
        :param secondary_smod_login: Login address for Secondary SMOD.
        :param secondary_smod_password: Password address for Secondary SMOD.
        :param secondary_smod_prompt: Prompt regex for Secondary SMOD state.
        :param port: port for telnet/TTY connection.
        :return: Nothing.
        """
        secondary_smod = (secondary_smod_host and secondary_smod_login
                          and secondary_smod_password and secondary_smod_prompt)
        proxy_pc = proxy_pc_host and proxy_pc_login and proxy_pc_password
        bts = bts_host and bts_login and bts_password

        passwords = password if isinstance(password, (list, set)) else password.split(',')
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.ru.RadioUnit',
                'INITIAL_STATE': initial_state,
                'CONNECTION_HOPS': {
                },
                "ADDITIONAL_PARAMS": {
                    "serial_number": serial_number
                }
            }
        }

        ru_params = {
            'command_params': {
                'host': host,
                'login': login,
                'password': passwords,
                'set_timeout': None
            }
        }

        connection_hops = config[device_name]['CONNECTION_HOPS']

        if proxy_pc:
            connection_hops['UNIX_LOCAL'] = {
                'PROXY_PC': self._build_execute_command_ssh(host=proxy_pc_host, login=proxy_pc_login,
                                                            password=proxy_pc_password)}

        if secondary_smod:
            secondary_smod_params = {
                'MASTER': {
                    'BTS': self._build_execute_command_ssh(
                        host=secondary_smod_host, login=secondary_smod_login,
                        password=secondary_smod_password, prompt=secondary_smod_prompt)
                },
                'BTS': {
                    'MASTER': {'command_params': {'expected_prompt': bts_prompt}}
                },
                'FHNET': {
                    'BTS': {'command_params': {'expected_prompt': secondary_smod_prompt}},
                    'RU': ru_params
                }
            }
            if proxy_pc:
                secondary_smod_params.update({
                    'PROXY_PC': {
                        'MASTER': {'command_params': {
                            'expected_prompt': bts_prompt,
                            'host': bts_host,
                            'login': bts_login,
                            'password': bts_password}}}})
                secondary_smod_params['MASTER']['PROXY_PC'] = {
                    'command_params': {
                        'expected_prompt': self._build_default_propmt(login=proxy_pc_login)}}
            else:
                secondary_smod_params.update({
                    'UNIX_LOCAL': {'MASTER': {'command_params': {'expected_prompt': bts_prompt}}}})

            connection_hops.update(secondary_smod_params)
        elif bts:
            bts_params = {
                'FHNET': {
                    'RU': ru_params}}
            if proxy_pc:
                bts_params.update({
                    'PROXY_PC': {
                        'BTS': {
                            'command_params': {'host': bts_host,
                                               'login': bts_login,
                                               'password': bts_password,
                                               'set_timeout': None}}},
                    'BTS': {
                        'PROXY_PC': {
                            'command_params': {
                                'expected_prompt': self._build_default_propmt(login=proxy_pc_login)}}}})
            else:
                bts_params.update({
                    'UNIX_LOCAL': {
                        'BTS': {
                            'command_params': {'host': bts_host,
                                               'login': bts_login,
                                               'password': bts_password,
                                               'set_timeout': None}}}})

            connection_hops.update(bts_params)
        else:
            if port:
                ru_params = {
                    'execute_command': 'telnet',
                    'command_params': {
                        'host': host,
                        'port': port,
                        'login': login,
                        'password': passwords,
                        'set_timeout': None
                    }
                }
            if proxy_pc:
                connection_hops['PROXY_PC'] = {'RU': ru_params}
                connection_hops['RU'] = {'PROXY_PC': {'command_params': {
                    'expected_prompt': self._build_default_propmt(login=proxy_pc_login)}}}
            else:
                connection_hops['UNIX_LOCAL'] = {'RU': ru_params}

        self._config['DEVICES'].update(config)

    def add_airscale_configuration(self, device_name, proxy_pc_host, proxy_pc_login,
                                   proxy_pc_password, fct_host=None, fsp_host=None, login=None, password=None,
                                   lxc_node='0xe019', initial_state='FCT', fct_prompt=None,
                                   secondary_smod_host=None, secondary_smod_login=None,
                                   secondary_smod_password=None, secondary_smod_prompt=None, fhnet_node=None):
        """
        Add airscale configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param fct_host: FCT host address. Required parameter to ssh connection.
        :param fsp_host: FSP host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password. Required parameter to ssh connection.
        :param proxy_pc_host: Proxy_pc host address. Required parameter to ssh connection.
        :param proxy_pc_login: Proxy_pc user login. Required parameter to ssh connection.
        :param proxy_pc_password: Proxy_pc user password address. Required parameter to ssh connection.
        :param lxc_node: address to lxc node eg: 0xe019
        :param fhnet_node: address to fhnet node eg: 0x1018/0x2018
        :param initial_state: initial state of the device - default FCT
        :param fct_prompt: Prompt regex for FCT state.
        :param secondary_smod_host: IP address for Secondary SMOD.
        :param secondary_smod_login: Login address for Secondary SMOD.
        :param secondary_smod_password: Password address for Secondary SMOD.
        :param secondary_smod_prompt: Prompt regex for Secondary SMOD state.

        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.air_scale.AirScale',
                'INITIAL_STATE': initial_state,
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'PROXY_PC': self._build_execute_command_ssh(host=proxy_pc_host, login=proxy_pc_login,
                                                                    password=proxy_pc_password)
                    },
                }
            }
        }
        connection_hops = config[device_name]['CONNECTION_HOPS']
        if secondary_smod_host and secondary_smod_login and secondary_smod_password and secondary_smod_prompt:
            secondary_smod_expected_prompt = {'command_params': {'expected_prompt': secondary_smod_prompt}}
            master_params = {'expected_prompt': fct_prompt}
            if fct_host and login and password:
                master_params.update({
                    'host': fct_host,
                    'login': login,
                    'password': password,
                })
            config_with_secondary_smod = {
                'PROXY_PC': {
                    'MASTER': {'command_params': master_params}
                },
                'MASTER': {
                    'FCT': self._build_execute_command_ssh(
                        host=secondary_smod_host, login=secondary_smod_login,
                        password=secondary_smod_password, prompt=secondary_smod_prompt),
                    'PROXY_PC': {
                        'command_params': {
                            'expected_prompt': self._build_default_propmt(login=proxy_pc_login),
                        }
                    },
                },
                'FCT': {
                    'MASTER': {'command_params': {'expected_prompt': fct_prompt}},
                    'LXC': {"command_params": {"name": lxc_node}},
                    'FHNET': {"command_params": {"name": fhnet_node}},
                },
                'FSP': {'FCT': secondary_smod_expected_prompt},
                'AASHELL': {'FCT': secondary_smod_expected_prompt},
                'LXC': {'FCT': secondary_smod_expected_prompt},
                'FHNET': {'FCT': secondary_smod_expected_prompt}
            }

            connection_hops.update(config_with_secondary_smod)

            if fsp_host and login and password:
                connection_hops['FCT']['FSP'] = self._build_execute_command_ssh(host=fsp_host, login=login,
                                                                                password=password,
                                                                                set_default_prompt=False)
        else:
            connection_hops['FCT'] = {
                'PROXY_PC': {
                    'command_params': {
                        'expected_prompt': self._build_default_propmt(login=proxy_pc_login),
                    }
                },
                'LXC': {"command_params": {"name": lxc_node}},
                'FHNET': {"command_params": {"name": fhnet_node}}
            }
            if fct_host and login and password:
                connection_hops['PROXY_PC'] = {
                    'FCT': self._build_execute_command_ssh(host=fct_host, login=login, password=password,
                                                           set_default_prompt=False)
                }
            if fsp_host and login and password:
                connection_hops['FCT']['FSP'] = self._build_execute_command_ssh(host=fsp_host, login=login,
                                                                                password=password,
                                                                                set_default_prompt=False)
        self._config['DEVICES'].update(config)

    def add_cloud_bts_configuration(self, device_name, oam_host, oam_login='robot', oam_password='rastre1',
                                    proxy_pc_host=None, proxy_pc_login=None, proxy_pc_password=None):
        """
        Add Cloud BTS (for CU) configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param oam_host: OAM host address. Required parameter to ssh connection.
        :param oam_login: OAM login.
        :param oam_password: OAM password.
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.cloud_bts.CloudBts',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'OAM': {
                            'command_params': {
                                'host': oam_host,
                                'login': oam_login,
                                'password': oam_password
                            }
                        },
                        'SERVICE_USER': {
                            'command_params': {
                                'host': oam_host,
                            }
                        }
                    }
                }
            }
        }

        if proxy_pc_host is not None:
            self._add_proxy_pc_state(config[device_name], proxy_pc_host, proxy_pc_login, proxy_pc_password)
        self._config['DEVICES'].update(config)

