    def _add_rtg_cus_configuration(self, device_name, ue_sim, host, login, password, ctrl_number=1,
                                   root_password=None, initial_state='RTG', proxy_pc_host=None,
                                   proxy_pc_login=None, proxy_pc_password=None):
        """
        Add rtg/cus configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param ue_sim: RTG or CUS
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password. Required parameter to ssh connection.
        :param ctrl_number: Number of controller for schmmi state.
        :param root_password: Optional parameter. If given root account configuration is added.
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.{}.{}'.format(ue_sim.lower(), ue_sim),
                'INITIAL_STATE': initial_state,
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'WS': self._build_execute_command_ssh(host=host, login=login, password=password),
                    },
                    ue_sim: {
                        'WS': {
                            'command_params': {
                                'expected_prompt': self._build_default_propmt(login),
                            }
                        }
                    },
                    'WS': {
                        'SCHMMI': {
                            'command_params': {
                                'ctrl_number': ctrl_number,
                            }
                        }
                    },
                    'WS_ROOT': {
                        'WS': {
                            'command_params': {
                                'expected_prompt': self._build_default_propmt(login),
                            }
                        }
                    },
                    'SCHMMI': {
                        'WS': {
                            'command_params': {
                                'expected_prompt': self._build_default_propmt(login),
                            }
                        }
                    }
                }
            }
        }
        if root_password is not None:
            root_config = self._build_unix_remote_root(root_password=root_password, root_prompt=r"root@.*?:.*#\s+")
            config[device_name]['CONNECTION_HOPS']['WS']['WS_ROOT'] = root_config["UNIX_REMOTE_ROOT"]
        if proxy_pc_host is not None:
            self._add_proxy_pc_state(config[device_name], proxy_pc_host, proxy_pc_login, proxy_pc_password)
        self._config['DEVICES'].update(config)

