    def _build_default_propmt(self, login):
        """
        Build default prompt with login.

        :param login: Username. Prompt beginning.
        :return: Prompt.
        """
        if login:
            login = re.escape(login)
        return "{}{}".format(login, r'@.*(\$|#|>)\s+')

    def _build_execute_command_ssh(self, host, login, password, prompt=None, set_default_prompt=True,
                                   set_timeout_none=True, **kwargs):
        """
        Return dictionary with execute_command ssh.

        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param set_default_prompt: Set True to set default prompt if not provided.
        :param set_timeout_none: Set True to set timeout to None if not provided
        :return: Dictionary with execute_command ssh.
        """
        ssh_command = {
            'execute_command': 'ssh',
            'command_params': {
                'host': host,
                'login': login,
                'password': password,
            }
        }
        ssh_command['command_params'].update(kwargs)

        if set_timeout_none and 'set_timeout' not in ssh_command:
            ssh_command['command_params']['set_timeout'] = None

        if prompt:
            ssh_command['command_params']['expected_prompt'] = prompt
        else:
            if set_default_prompt:
                ssh_command['command_params']['expected_prompt'] = self._build_default_propmt(login=login)
        return ssh_command

    def _build_execute_command_telnet(self, host, port):
        """
        Return dictionary with execute_command telnet.

        :param host: Host address. Required parameter to telnet connection.
        :param port: Port number. Required parameter to telnet connection.
        :return: Dictionary with execute_command telnet.
        """
        telnet_command = {
            'execute_command': 'telnet',
            'command_params': {
                'host': host,
                'port': port,
                'set_timeout': None
            }
        }
        return telnet_command

