    def add_rtg_controller_configuration(self, device_name, host,
                                         login=None, password=None, prompt=None,
                                         proxy_pc_host=None, proxy_pc_login=None,
                                         proxy_pc_password=None, proxy_pc_prompt=None, dsp_number=1):
        """
        Add rtg controller configuration to config dictionary (with proxy PC).

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection. IP of controller unit
        :param login: Optional parameter. Login for controller unit
        :param password: Optional parameter. Password for controller unit
        :param proxy_pc_host: Optional parameter. IP of proxy PC
        :param proxy_pc_login: Optional parameter. Login for proxy pc
        :param proxy_pc_password: Optional parameter. Password for login PC
        :param proxy_pc_prompt: Optional parameter. Prompt for proxy PC

        :return: Nothing.
        """
        command_params = {}
        command_params['host'] = host
        if login:
            command_params['login'] = login
        if password:
            command_params['password'] = password
        if prompt:
            command_params['expected_prompt'] = prompt

        config = {
            device_name: {
                "DEVICE_CLASS": "ta_moler.device.rtg_controller.RtgController",
                "CONNECTION_HOPS": {
                    "UNIX_LOCAL": {
                        "PROXY_PC": self._build_execute_command_ssh(host=proxy_pc_host, login=proxy_pc_login,
                                                                    password=proxy_pc_password,
                                                                    prompt=proxy_pc_prompt,
                                                                    set_default_prompt=True),
                    },
                    "PROXY_PC": {
                        "LINUX": {
                            "command_params": command_params
                        }
                    },
                    "LINUX": {
                        "PROXY_PC": {
                            "command_params": {
                                "expected_prompt": proxy_pc_prompt
                            }
                        },
                        "DSP": {
                            "command_params": {
                                "dsp_number": dsp_number,

                            }
                        }
                    }
                }
            }
        }

        self._config['DEVICES'].update(config)

    def add_adbremote_configuration(self, device_name, host, login, password, serial_number,
                                    adb_prompt=None, prompt=None, adb_root_password=None, adb_root_prompt=None):
        """
        Add ADB remote configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param serial_number: serial number of UE device
        :param adb_prompt: Optional parameter, prompt for adb shell
        :param prompt: Optional parameter. If not passed, default used
        :param adb_root_password: Optional parameter. If not passed, default used
        :param adb_root_prompt: Optional parameter. If not passed, default used
        :return: Nothing.
        """

        pc_prompt = prompt if prompt else self._build_default_propmt(login=login)

        config = {
            device_name: {
                'DEVICE_CLASS': 'moler.device.adbremote.AdbRemote',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'UNIX_REMOTE': self._build_execute_command_ssh(host=host,
                                                                       login=login,
                                                                       password=password,
                                                                       prompt=pc_prompt)
                    },
                    'UNIX_REMOTE': {
                        'ADB_SHELL': {
                            'command_params': {
                                'serial_number': serial_number,
                                'expected_prompt': adb_prompt
                            }
                        }},
                    'ADB_SHELL': {
                        'UNIX_REMOTE': {
                            'command_params': {
                                'expected_prompt': pc_prompt
                            }},
                        'ADB_SHELL_ROOT': {
                            'command_params': {
                                'password': adb_root_password,
                                'expected_prompt': adb_root_prompt
                            }}},
                    'ADB_SHELL_ROOT': {
                        'ADB_SHELL': {
                            'command_params': {
                                'expected_prompt': adb_prompt
                            }}}
                }
            }
        }

        self._config['DEVICES'].update(config)

    def add_egen_configuration(self, device_name, host, login, password, root_password=None,
                               root_prompt=r"root@.*?:.*#\s+",
                               proxy_pc_host=None, proxy_pc_login=None, proxy_pc_password=None, **kwargs):
        """
        Add egen configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param root_password: Optional parameter. If given root account configuration is added
        :param root_prompt: Optional parameter. Needed if root prompt is different than defined one
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.egen.Egen',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'UNIX_REMOTE': self._build_execute_command_ssh(host=host,
                                                                       login=login,
                                                                       password=password,
                                                                       **kwargs)
                    }
                }
            }
        }
        if root_password is not None:
            config[device_name]['CONNECTION_HOPS']['UNIX_REMOTE'] = self._build_unix_remote_root(root_password,
                                                                                                 root_prompt)
        if proxy_pc_host is not None:
            self._add_proxy_pc_state(config[device_name], proxy_pc_host, proxy_pc_login, proxy_pc_password)

        self._config['DEVICES'].update(config)

    def add_at_remote_configuration(self, device_name, host, login, password, serial_com,
                                    unix_remote_prompt=r".*user-lab0@.*", proxy_pc_host=None, proxy_pc_login=None,
                                    proxy_pc_password=None, **kwargs):
        """
        Add AtRemote configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param serial_com: COM ID obtained from modem
        :param unix_remote_prompt: Optional parameter. Needed if unix remote prompt is different than defined one
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :return: Nothing.
        """
        config = {
            device_name: {
                'DEVICE_CLASS': 'moler.device.atremote.AtRemote',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'UNIX_REMOTE': self._build_execute_command_ssh(host=host,
                                                                       login=login,
                                                                       password=password,
                                                                       prompt=unix_remote_prompt,
                                                                       **kwargs)
                    },
                    'UNIX_REMOTE': {
                        'AT_REMOTE': {
                            'command_params': {
                                'serial_devname': 'COM' + serial_com
                            }
                        }}
                }
            }
        }
        if proxy_pc_host is not None:
            self._add_proxy_pc_state(config[device_name], proxy_pc_host, proxy_pc_login, proxy_pc_password)

        self._config['DEVICES'].update(config)

    def add_nom_configuration(self, device_name, host, login, password, private_key=None,
                              proxy_pc_host=None, proxy_pc_login=None, proxy_pc_password=None):
        """
        Add nom configuration to config dictionary.

        :param device_name: The name of the device that will be created.
        :param host: Host address. Required parameter to ssh connection.
        :param login: User login. Required parameter to ssh connection.
        :param password: User password address. Required parameter to ssh connection.
        :param private_key: path to private key(option -i)
        :param proxy_pc_host: Optional parameter. IP of proxy PC.
        :param proxy_pc_login: Optional parameter. Login for proxy PC.
        :param proxy_pc_password: Optional parameter. Password for login PC.
        :return: Nothing.
        """

        options = '-o ServerAliveInterval=7 -o ServerAliveCountMax=2'
        if private_key:
            options = '{} -i {}'.format(options, private_key)
        self.add_remote_unix_configuration(device_name, host, login, password,
                                           proxy_pc_host=proxy_pc_host,
                                           proxy_pc_login=proxy_pc_login,
                                           proxy_pc_password=proxy_pc_password,
                                           options=options,
                                           )

    def add_positioner_1d_krk(self, device_name, host, login, password, unix_remote_prompt,
                              proxy_pc_host=None, proxy_pc_login=None, proxy_pc_password=None):
        config = {
            device_name: {
                'DEVICE_CLASS': 'ta_moler.device.positioner_1d_krk.Positioner1DKrk',
                'CONNECTION_HOPS': {
                    'UNIX_LOCAL': {
                        'UNIX_REMOTE': self._build_execute_command_ssh(host=host,
                                                                       login=login,
                                                                       password=password,
                                                                       prompt=unix_remote_prompt,
                                                                       set_default_prompt=False,
                                                                       set_timeout_none=False)
                    },
                    'UNIX_REMOTE_POSITIONER': {
                        'POSITIONER': {
                            'password': password
                        }
                    }
                }
            }
        }
        if proxy_pc_host is not None:
            self._add_proxy_pc_state(config[device_name], proxy_pc_host, proxy_pc_login, proxy_pc_password)

        self._config['DEVICES'].update(config)

    def _build_unix_local_root(self, root_password, root_prompt=r"root@.*?:.*#\s+", cmd='sudo'):
        """
        Return dictionary with UNIX_LOCAL_ROOT part of configuration .

        :param root_password: Optional parameter. If given root account configuration is added
        :param root_prompt: Optional parameter. Needed if root prompt is different than defined one
        :return: Dictionary with execute_command telnet.
        """
        if cmd == 'su':
            local_root = {
                'UNIX_LOCAL_ROOT': {
                    "command_params": {
                        "password": root_password,
                        "expected_prompt": root_prompt
                    }
                }
            }
        else:
            local_root = {
                'UNIX_LOCAL_ROOT': {
                    "execute_command": 'sudo',
                    "command_params": {
                        "sudo_params": '-i',
                        "expected_prompt": root_prompt
                    }
                }
            }
        return local_root

    def _build_unix_remote_root(self, root_password, root_prompt=r"root@.*?:.*#\s+", cmd='su'):
        """
        Return dictionary with UNIX_REMOTE_ROOT part of configuration .

        :param root_password: Optional parameter. If given root account configuration is added
        :param root_prompt: Optional parameter. Needed if root prompt is different than defined one
        :return: Dictionary with execute_command telnet.
        """
        if cmd == 'su':
            remote_root = {
                'UNIX_REMOTE_ROOT': {
                    "command_params": {
                        "password": root_password,
                        "expected_prompt": root_prompt
                    }
                }
            }
        else:
            remote_root = {
                'UNIX_REMOTE_ROOT': {
                    "execute_command": 'sudo',
                    "command_params": {
                        "sudo_params": '-i',
                        "expected_prompt": root_prompt
                    }
                }
            }
        return remote_root

    def _add_proxy_pc_state(self, device_config, proxy_pc_host, proxy_pc_login, proxy_pc_password):
        """
        Add proxy pc state to device configuration.

        :param device_config: Device config dictionary for which proxy pc state will be added.
        :param proxy_pc_host: IP of proxy PC.
        :param proxy_pc_login: Login for proxy PC.
        :param proxy_pc_password: Password for login PC.
        :return: None
        """
        connection_hops = device_config['CONNECTION_HOPS']
        unix_local_hops = connection_hops['UNIX_LOCAL']
        hop_to_unix_local_root = unix_local_hops.pop("UNIX_LOCAL_ROOT", None)

        connection_hops['UNIX_LOCAL'] = {}
        if hop_to_unix_local_root:
            connection_hops['UNIX_LOCAL']['UNIX_LOCAL_ROOT'] = hop_to_unix_local_root
        connection_hops['UNIX_LOCAL']['PROXY_PC'] = self._build_execute_command_ssh(host=proxy_pc_host,
                                                                                    login=proxy_pc_login,
                                                                                    password=proxy_pc_password)
        connection_hops['PROXY_PC'] = unix_local_hops

        for state in unix_local_hops:
            connection_hops[state] = {'PROXY_PC': {
                'command_params': {
                    'expected_prompt': self._build_default_propmt(proxy_pc_login)}}
            }
